166			return nil, status.Errorf(codes.InvalidArgument, "invalid notification name: %v", err)
167		}
168	
169		currentUser, err := s.fetchCurrentUser(ctx)
170		if err != nil {
171			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
172		}
173	
174		if currentUser == nil {
175			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
176		}
177		if currentUser.ID != user.ID {
178			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
179		}
180		// Verify ownership before deletion
181		inboxes, err := s.Store.ListInboxes(ctx, &store.FindInbox{
182			ID: &notificationID,
183		})
184		if err != nil {
185			return nil, status.Errorf(codes.Internal, "failed to get inbox: %v", err)
