149	func (s *APIV1Service) convertMemoRelationFromStore(ctx context.Context, memoRelation *store.MemoRelation) (*v1pb.MemoRelation, error) {
150		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &memoRelation.MemoID})
151		if err != nil {
152			return nil, status.Errorf(codes.Internal, "failed to get memo: %v", err)
153		}
154		memoSnippet, err := s.getMemoContentSnippet(memo.Content)
155		if err != nil {
156			return nil, errors.Wrap(err, "failed to get memo content snippet")
157		}
158		relatedMemo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &memoRelation.RelatedMemoID})
159		if err != nil {
160			return nil, status.Errorf(codes.Internal, "failed to get related memo: %v", err)
161		}
162		relatedMemoSnippet, err := s.getMemoContentSnippet(relatedMemo.Content)
163		if err != nil {
164			return nil, errors.Wrap(err, "failed to get related memo content snippet")
165		}
166		return &v1pb.MemoRelation{
167			Memo: &v1pb.MemoRelation_Memo{
168				Name:    fmt.Sprintf("%s%s", MemoNamePrefix, memo.UID),
169				Snippet: memoSnippet,
170			},
171			RelatedMemo: &v1pb.MemoRelation_Memo{
172				Name:    fmt.Sprintf("%s%s", MemoNamePrefix, relatedMemo.UID),
173				Snippet: relatedMemoSnippet,
174			},
175			Type: convertMemoRelationTypeFromStore(memoRelation.Type),
176		}, nil
177	}
178	
179	func convertMemoRelationTypeFromStore(relationType store.MemoRelationType) v1pb.MemoRelation_Type {
180		switch relationType {
181		case store.MemoRelationReference:
182			return v1pb.MemoRelation_REFERENCE
183		case store.MemoRelationComment:
184			return v1pb.MemoRelation_COMMENT
185		default:
186			return v1pb.MemoRelation_TYPE_UNSPECIFIED
187		}
188	}
189	
190	func convertMemoRelationTypeToStore(relationType v1pb.MemoRelation_Type) store.MemoRelationType {
191		switch relationType {
192		case v1pb.MemoRelation_COMMENT:
193			return store.MemoRelationComment
194		default:
195			return store.MemoRelationReference
196		}
197	}
