1	package v1
2	
3	import (
4		"encoding/base64"
5	
6		"github.com/pkg/errors"
7		"google.golang.org/protobuf/proto"
8	
9		v1pb "github.com/usememos/memos/proto/gen/api/v1"
10		"github.com/usememos/memos/store"
11	)
12	
13	const (
14		// DefaultPageSize is the default page size for requests.
15		DefaultPageSize = 50
16		// MaxPageSize is the maximum page size for requests.
17		MaxPageSize = 1000
18	)
19	
20	func convertStateFromStore(rowStatus store.RowStatus) v1pb.State {
21		switch rowStatus {
22		case store.Normal:
23			return v1pb.State_NORMAL
24		case store.Archived:
25			return v1pb.State_ARCHIVED
26		default:
27			return v1pb.State_STATE_UNSPECIFIED
28		}
29	}
30	
31	func convertStateToStore(state v1pb.State) store.RowStatus {
32		switch state {
33		case v1pb.State_ARCHIVED:
34			return store.Archived
35		default:
36			return store.Normal
37		}
38	}
39	
40	func getPageToken(limit int, offset int) (string, error) {
41		return marshalPageToken(&v1pb.PageToken{
42			Limit:  int32(limit),
43			Offset: int32(offset),
44		})
45	}
46	
47	func normalizePageSize(pageSize int32) int {
48		limit := int(pageSize)
49		if limit <= 0 {
50			return DefaultPageSize
51		}
52		if limit > MaxPageSize {
53			return MaxPageSize
54		}
55		return limit
56	}
57	
58	func marshalPageToken(pageToken *v1pb.PageToken) (string, error) {
59		b, err := proto.Marshal(pageToken)
60		if err != nil {
61			return "", errors.Wrapf(err, "failed to marshal page token")
62		}
63		return base64.StdEncoding.EncodeToString(b), nil
64	}
65	
66	func unmarshalPageToken(s string, pageToken *v1pb.PageToken) error {
67		b, err := base64.StdEncoding.DecodeString(s)
68		if err != nil {
69			return errors.Wrapf(err, "failed to decode page token")
70		}
71		if err := proto.Unmarshal(b, pageToken); err != nil {
72			return errors.Wrapf(err, "failed to unmarshal page token")
73		}
74		return nil
75	}
76	
77	func isSuperUser(user *store.User) bool {
78		return user.Role == store.RoleAdmin
79	}
80	
81	func canModifyMemo(user *store.User, memo *store.Memo) bool {
82		return user != nil && memo != nil && (memo.CreatorID == user.ID || isSuperUser(user))
83	}
